	parsedURL, err := url.Parse(redirectPath)
	if err != nil {
		return fmt.Errorf("invalid redirect URL: %w", err)
	}

	// If it's an absolute URL, validate the host
	if parsedURL.IsAbs() {
		hostAllowed := false
		for _, allowedHost := range allowedRedirectHosts {
			if strings.EqualFold(parsedURL.Host, allowedHost) || 
