				hostAllowed = true
				break
			}
		}
		if !hostAllowed {
			return fmt.Errorf("redirect host not allowed: %s", parsedURL.Host)
		}

		// Ensure the scheme is HTTPS
		if parsedURL.Scheme != "https" {
			return fmt.Errorf("redirect URL must use HTTPS scheme")
		}
	}

	return nil
}

