)

var OAuthConfig = &oauth2.Config{
	ClientID:     "your-client-id",
	ClientSecret: "your-client-secret",
	RedirectURL:  "https://yourapp.com/callback",
	Scopes:       []string{"openid", "profile", "email"},
	Endpoint: oauth2.Endpoint{
		AuthURL:  "https://provider.com/oauth2/authorize",
		TokenURL: "https://provider.com/oauth2/token",
	},
}

// allowedRedirectPaths contains the list of allowed redirect paths after authentication
var allowedRedirectPaths = map[string]bool{
	"/":          true,
	"/dashboard": true,
	"/profile":   true,
	"/settings":  true,
}

// generateSecureState creates a cryptographically secure random state string
func generateSecureState() (string, error) {
	b := make([]byte, 32)
	_, err := rand.Read(b)
	if err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(b), nil
}

// validateRedirectPath validates that the redirect path is safe and allowed
func validateRedirectPath(redirectPath string) (string, error) {
	if redirectPath == "" {
		return "/", nil
	}

	// Parse the redirect path
	parsed, err := url.Parse(redirectPath)
	if err != nil {
		return "", errors.New("invalid redirect path")
	}

	// Ensure it's a relative path (no scheme or host) to prevent open redirect
	if parsed.Scheme != "" || parsed.Host != "" {
		return "", errors.New("absolute URLs are not allowed for redirect path")
	}

	// Normalize the path
	cleanPath := parsed.Path
	if !strings.HasPrefix(cleanPath, "/") {
		cleanPath = "/" + cleanPath
	}

	// Check against allowlist
	if !allowedRedirectPaths[cleanPath] {
		return "", errors.New("redirect path not allowed")
	}

	return cleanPath, nil
}

// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Validate the redirect path to prevent open redirect attacks
	validatedPath, err := validateRedirectPath(redirectPath)
	if err != nil {
		return "", err
	}

	// Generate a cryptographically secure random state
	state, err := generateSecureState()
	if err != nil {
		return "", err
	}

	// Use the configured RedirectURL from OAuthConfig (don't allow user to override it)
	// The validatedPath is stored separately for post-auth redirect within our app
	authURL := OAuthConfig.AuthCodeURL(state)

	// Set the state in a secure cookie for later validation
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
		MaxAge:   600, // 10 minutes expiration
	})

	// Store the validated redirect path in a separate cookie for post-auth redirect
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_redirect",
		Value:    validatedPath,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
		MaxAge:   600, // 10 minutes expiration
	})

	return authURL, nil
