}

// validateRedirectURL validates that the redirect URL is safe and allowed
func validateRedirectURL(redirectPath string) error {
	if redirectPath == "" {
		return errors.New("redirect path cannot be empty")
	}

	// Parse the redirect URL
	parsedURL, err := url.Parse(redirectPath)
	if err != nil {
		return errors.New("invalid redirect URL format")
	}

	// Check for path traversal in any case
	if strings.Contains(redirectPath, "..") {
		return errors.New("path traversal not allowed")
	}

	// If it's an absolute URL, validate the host
	if parsedURL.IsAbs() {
